rollback.sql:
DELETE FROM configurator_questions
 WHERE code IN ('BUSINESS_TYPE','MEDICAL_CONSULTATIONS','SELLS_PRODUCTS',
                'CHARGES_AT_COUNTER','TERMINAL_COUNT','USER_COUNT');

UPDATE configurator_questions
   SET parent_option_id = NULL, version = version + 1
 WHERE code = 'TERMINAL_COUNT';

DELETE ce FROM configurator_effects ce
  JOIN configurator_questions q ON q.id = ce.question_id
 WHERE q.code IN ('TERMINAL_COUNT','USER_COUNT');
